<?php
/** BubbaHub My Hub group collections and recommendation engine. */
if ( ! defined( 'ABSPATH' ) ) exit;
add_action( 'wp_enqueue_scripts', 'bubbahub_myhub_groups_assets' );
add_action( 'wp_ajax_bubbahub_myhub_groups', 'bubbahub_myhub_groups_ajax' );
add_action( 'init', 'bubbahub_myhub_groups_create_page' );
add_shortcode( 'bubbahub_myhub_groups', 'bubbahub_myhub_groups_shortcode' );
function bubbahub_myhub_groups_assets(){if(!is_user_logged_in())return;wp_register_style('bubbahub-myhub-groups',BUBBAHUB_MYHUB_URL.'myhub-groups.css',array(),BUBBAHUB_MYHUB_VERSION);wp_register_script('bubbahub-myhub-groups',BUBBAHUB_MYHUB_URL.'myhub-groups.js',array('jquery'),BUBBAHUB_MYHUB_VERSION,true);wp_localize_script('bubbahub-myhub-groups','BubbaHubMyHubGroups',array('ajaxUrl'=>admin_url('admin-ajax.php'),'nonce'=>wp_create_nonce('bubbahub_myhub_groups'),'pageUrl'=>home_url('/my-groups/')));}
function bubbahub_myhub_groups_create_page(){if(get_option('bubbahub_myhub_groups_page_created'))return;$page=get_page_by_path('my-groups');if(!$page){$id=wp_insert_post(array('post_title'=>'My Groups','post_name'=>'my-groups','post_content'=>'[bubbahub_myhub_groups]','post_status'=>'publish','post_type'=>'page'),true);if(!is_wp_error($id))update_option('bubbahub_myhub_groups_page_created',1,false);}else update_option('bubbahub_myhub_groups_page_created',1,false);}
function bubbahub_myhub_groups_clean_ids($ids){$ids=is_array($ids)?$ids:array();$ids=array_values(array_unique(array_filter(array_map('absint',$ids))));if(!$ids)return array();return array_map('absint',get_posts(array('post_type'=>'group','post_status'=>'publish','post__in'=>$ids,'posts_per_page'=>count($ids),'fields'=>'ids','orderby'=>'post__in','no_found_rows'=>true)));}
function bubbahub_myhub_groups_card($post_id){$title=get_the_title($post_id);$url=get_permalink($post_id);$image=function_exists('bubbahub_directory_image_url')?bubbahub_directory_image_url($post_id):get_the_post_thumbnail_url($post_id,'medium_large');$region=function_exists('bubbahub_directory_region')?bubbahub_directory_region($post_id):'';$age=function_exists('bubbahub_directory_get_field')?bubbahub_directory_get_field($post_id,'age_range'):get_post_meta($post_id,'age_range',true);$price=function_exists('bubbahub_directory_get_field')?bubbahub_directory_get_field($post_id,'price'):get_post_meta($post_id,'price',true);if(is_array($age))$age=implode(', ',$age);if(is_array($price))$price=implode(', ',$price);ob_start();?><article class="bh-myhub-group-card" data-group-id="<?php echo esc_attr($post_id); ?>"><a class="bh-myhub-group-image" href="<?php echo esc_url($url); ?>"><?php if($image):?><img src="<?php echo esc_url($image); ?>" alt="<?php echo esc_attr($title); ?>" loading="lazy"><?php else:?><span>BubbaHub</span><?php endif;?></a><div class="bh-myhub-group-body"><h3><a href="<?php echo esc_url($url); ?>"><?php echo esc_html($title);?></a></h3><?php if($region):?><div class="bh-myhub-group-meta">⌖ <?php echo esc_html($region);?></div><?php endif;?><div class="bh-myhub-group-tags"><?php if($age):?><span><?php echo esc_html($age);?></span><?php endif;?><?php if($price):?><span><?php echo esc_html($price);?></span><?php endif;?></div><a class="bh-myhub-group-view" href="<?php echo esc_url($url);?>">View group <span>→</span></a></div></article><?php return ob_get_clean();}
function bubbahub_myhub_groups_user_preferences(){ $i=(array)get_user_meta(get_current_user_id(),'user_interests',true);$l=(array)get_user_meta(get_current_user_id(),'preferred_locations',true);if(function_exists('get_field')){ $ai=get_field('user_interests','user_'.get_current_user_id(),false);$al=get_field('preferred_locations','user_'.get_current_user_id(),false);if($ai!==null&&$ai!==false)$i=(array)$ai;if($al!==null&&$al!==false)$l=(array)$al;}return array(array_map('sanitize_key',$i),array_map('absint',$l));}
function bubbahub_myhub_groups_age_tokens(){ $children=get_posts(array('post_type'=>'bh_child','post_status'=>'publish','author'=>get_current_user_id(),'posts_per_page'=>-1,'fields'=>'ids','no_found_rows'=>true));$tokens=array();$selected=(array)get_user_meta(get_current_user_id(),'bh_myhub_selected_children',true);$selected=array_map('absint',$selected);foreach($children as $id){if($selected&& !in_array($id,$selected,true))continue;$status=function_exists('get_field')?get_field('child_status',$id):get_post_meta($id,'child_status',true);if($status==='expecting')continue;$dob=function_exists('get_field')?get_field('child_date_of_birth',$id):get_post_meta($id,'child_date_of_birth',true);if(!$dob)continue;$b=new DateTime($dob);$t=new DateTime('today');if($b>$t)continue;$m=($b->diff($t)->y*12)+$b->diff($t)->m;if($m<3)$tokens=array_merge($tokens,array('0-3','0 - 3 months'));elseif($m<6)$tokens=array_merge($tokens,array('3-6','3 - 6 months'));elseif($m<9)$tokens=array_merge($tokens,array('6-9','6 - 9 months'));elseif($m<12)$tokens=array_merge($tokens,array('9-12','9 - 12 months'));elseif($m<24)$tokens=array_merge($tokens,array('1-3','1 - 3 years'));elseif($m<36)$tokens=array_merge($tokens,array('1-3','1 - 3 years','2-4','2 - 4 years'));elseif($m<48)$tokens=array_merge($tokens,array('2-4','2 - 4 years','3-5','3 - 5 years'));elseif($m<60)$tokens=array_merge($tokens,array('3-5','3 - 5 years','5-plus','5+'));else $tokens=array_merge($tokens,array('5-plus','5+'));}return array_values(array_unique($tokens));}
function bubbahub_myhub_groups_score($id,$interests,$locations,$ages){$score=0;$terms=get_the_terms($id,'location');if(!is_wp_error($terms)&&$locations){foreach($terms as $t)if(in_array((int)$t->term_id,$locations,true)){$score+=4;break;}}$interest_match=false;if($interests&&taxonomy_exists('interest')){$terms=get_the_terms($id,'interest');if(!is_wp_error($terms))foreach($terms as $t)if(in_array($t->slug,$interests,true)||in_array($t->name,$interests,true)){$interest_match=true;break;}}if(!$interest_match&&$interests){foreach(array('interests','interest','activity_type') as $field){$v=function_exists('bubbahub_directory_get_field')?bubbahub_directory_get_field($id,$field):get_post_meta($id,$field,true);$hay=strtolower(is_array($v)?implode(' ',array_map('strval',$v)):strval($v));foreach($interests as $i){if($hay!==''&&strpos($hay,strtolower($i))!==false){$interest_match=true;break 2;}}}}if($interest_match)$score+=3;if($ages){$v=function_exists('bubbahub_directory_get_field')?bubbahub_directory_get_field($id,'age_range'):get_post_meta($id,'age_range',true);$hay=strtolower(is_array($v)?implode(' ',array_map('strval',$v)):strval($v));foreach($ages as $a)if($hay!==''&&strpos($hay,strtolower($a))!==false){$score+=3;break;}}return $score;}
function bubbahub_myhub_groups_suggested_ids($exclude=array()){list($interests,$locations)=bubbahub_myhub_groups_user_preferences();$ages=bubbahub_myhub_groups_age_tokens();$q=new WP_Query(array('post_type'=>'group','post_status'=>'publish','posts_per_page'=>100,'post__not_in'=>array_map('absint',$exclude),'orderby'=>'date','order'=>'DESC','no_found_rows'=>true));$scored=array();while($q->have_posts()){$q->the_post();$id=get_the_ID();$s=bubbahub_myhub_groups_score($id,$interests,$locations,$ages);if($s>0)$scored[$id]=$s;}wp_reset_postdata();arsort($scored,SORT_NUMERIC);$ids=array_keys($scored);if(count($ids)<12){$fallback=get_posts(array('post_type'=>'group','post_status'=>'publish','posts_per_page'=>24,'post__not_in'=>array_merge(array_map('absint',$exclude),array_map('absint',$ids)),'fields'=>'ids','orderby'=>'date','order'=>'DESC','no_found_rows'=>true));$ids=array_merge($ids,$fallback);}return array_slice(array_values(array_unique(array_map('absint',$ids))),0,24);}
function bubbahub_myhub_groups_ajax(){if(!is_user_logged_in())wp_send_json_error(array('message'=>'Please log in.'),401);check_ajax_referer('bubbahub_myhub_groups','nonce');$type=isset($_POST['type'])?sanitize_key(wp_unslash($_POST['type'])):'favourite';$ids=isset($_POST['ids'])?json_decode(wp_unslash($_POST['ids']),true):array();$ids=bubbahub_myhub_groups_clean_ids($ids);$favs=isset($_POST['favourites'])?json_decode(wp_unslash($_POST['favourites']),true):array();$visited=isset($_POST['visited'])?json_decode(wp_unslash($_POST['visited']),true):array();$recent=isset($_POST['recently_viewed'])?json_decode(wp_unslash($_POST['recently_viewed']),true):array();if($type==='suggested'){$exclude=array_merge($ids,bubbahub_myhub_groups_clean_ids($favs),bubbahub_myhub_groups_clean_ids($visited),bubbahub_myhub_groups_clean_ids($recent));$ids=bubbahub_myhub_groups_suggested_ids($exclude);}elseif($type==='recently_viewed')$ids=bubbahub_myhub_groups_clean_ids($recent);$html='';foreach(array_slice($ids,0,24) as $id)$html.=bubbahub_myhub_groups_card($id);wp_send_json_success(array('html'=>$html,'count'=>count($ids)));}
function bubbahub_myhub_groups_shortcode(){if(!is_user_logged_in())return '<div class="bh-myhub-login"><h2>My Groups</h2><p>Please log in to see your groups.</p></div>';wp_enqueue_style('bubbahub-myhub');wp_enqueue_style('bubbahub-myhub-groups');wp_enqueue_script('bubbahub-myhub-groups');$view=isset($_GET['group_view'])?sanitize_key(wp_unslash($_GET['group_view'])):'favourite';if(!in_array($view,array('recently_viewed','favourite','visited','suggested'),true))$view='favourite';$titles=array('recently_viewed'=>'Recently Viewed','favourite'=>'Favourite Groups','visited'=>'Visited Groups','suggested'=>'Suggested Groups');ob_start();?><div class="bh-myhub bh-myhub-groups-page" data-myhub-groups-page="<?php echo esc_attr($view);?>"><div class="bh-myhub-groups-page-head"><div><div class="bh-myhub-kicker">YOUR BUBBA HUB</div><h1><?php echo esc_html($titles[$view]);?></h1><p>Keep the local groups that matter to your family close at hand.</p></div><a class="bh-myhub-button secondary" href="<?php echo esc_url(home_url('/my-hub/'));?>">← Back to My Hub</a></div><div class="bh-myhub-groups-tabs"><?php foreach($titles as $key=>$label):?><a class="<?php echo $view===$key?'is-active':'';?>" href="<?php echo esc_url(add_query_arg('group_view',$key,home_url('/my-groups/')));?>"><?php echo esc_html($label);?></a><?php endforeach;?></div><div class="bh-myhub-groups-results" data-myhub-group-results data-group-view="<?php echo esc_attr($view);?>"><div class="bh-myhub-groups-loading">Loading your groups…</div></div></div><?php return ob_get_clean();}
